# qx2_chunk :: ([1, 2, 3, 4, 5], 2)
def qx2_chunk(xs, n):
    if n <= 0:
        return []
    return [xs[i:i + n] for i in range(0, len(xs), n)]

if __name__ == '__main__':
    print(qx2_chunk(([1, 2, 3, 4, 5], 2)))

